<?php
declare(strict_types=1);
session_start();
$root=dirname(__DIR__,3);$cfg=require $root.'/config.php';date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');
$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
if(!(bool)$db->query("SHOW COLUMNS FROM quotes LIKE 'quote_series_key'")->fetch())$db->exec("ALTER TABLE quotes ADD COLUMN quote_series_key CHAR(32) NULL AFTER project_id");
if(!(bool)$db->query("SHOW COLUMNS FROM quotes LIKE 'locked_at'")->fetch())$db->exec("ALTER TABLE quotes ADD COLUMN locked_at DATETIME NULL AFTER sent_at");
$db->exec("UPDATE quotes SET quote_series_key=LOWER(LEFT(SHA2(CONCAT(project_id,'|',quote_category,'|',COALESCE(NULLIF(TRIM(proposal_name),''),CONCAT('presupuesto-',id))),256),32)) WHERE quote_series_key IS NULL OR quote_series_key=''");
$statusType=(string)$db->query("SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='quotes' AND COLUMN_NAME='status'")->fetchColumn();
if(!str_contains($statusType,'aprobado_definitivo'))$db->exec("ALTER TABLE quotes MODIFY status ENUM('borrador','enviado','aprobado_inicial','aprobado_definitivo','final','rechazado') NOT NULL DEFAULT 'borrador'");
$oldUnique=$db->query("SELECT INDEX_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='quotes' AND NON_UNIQUE=0 AND INDEX_NAME<>'PRIMARY' GROUP BY INDEX_NAME HAVING GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX)='project_id,version_no' LIMIT 1")->fetchColumn();
if($oldUnique)$db->exec('ALTER TABLE quotes DROP INDEX `'.str_replace('`','``',(string)$oldUnique).'`');
$hasSeriesIndex=(int)$db->query("SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='quotes' AND INDEX_NAME='uq_quote_series_version'")->fetchColumn();
if(!$hasSeriesIndex)$db->exec("ALTER TABLE quotes MODIFY quote_series_key CHAR(32) NOT NULL, ADD UNIQUE KEY uq_quote_series_version (quote_series_key,version_no)");
$db->exec("CREATE TABLE IF NOT EXISTS erp_data_migrations (
 migration_key VARCHAR(190) PRIMARY KEY,
 applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$db->beginTransaction();
try{
 $claim=$db->prepare('INSERT IGNORE INTO erp_data_migrations(migration_key) VALUES(?)');
 $claim->execute(['2026-09-17-normalize-initial-quote-versions']);
 if($claim->rowCount()===1){
  $series=$db->query("SELECT quote_series_key FROM quotes WHERE quote_series_key<>'' GROUP BY quote_series_key HAVING COUNT(*)=1")->fetchAll(PDO::FETCH_COLUMN);
  $normalize=$db->prepare('UPDATE quotes SET version_no=1 WHERE quote_series_key=? AND version_no<>1');
  foreach($series as $seriesKey)$normalize->execute([(string)$seriesKey]);
 }
 $db->commit();
}catch(Throwable $migrationError){
 if($db->inTransaction())$db->rollBack();
 throw $migrationError;
}
