function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function usd($n):string{return 'US$ '.number_format(round((float)$n),0,',','.');}
$quotes=$db->query("SELECT q.*,p.project_number,p.name project_name,c.business_name,(SELECT COUNT(*) FROM quote_items qi WHERE qi.quote_id=q.id) item_count FROM quotes q JOIN projects p ON p.id=q.project_id JOIN clients c ON c.id=p.client_id ORDER BY q.quote_date DESC,q.id DESC")->fetchAll();$statusLabels=['borrador'=>'Borrador','enviado'=>'Enviado','aprobado_inicial'=>'Aceptado inicial','aprobado_definitivo'=>'Aceptado definitivo','final'=>'Aceptado definitivo','rechazado'=>'Rechazado'];$msg=$_SESSION['msg']??null;unset($_SESSION['msg']);
if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Presupuestos · Punto ERP</title><style><?=erpSidebarCss()?>body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}.main{margin-left:var(--sidebar);padding:32px 4%}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px}.row{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.top-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:8px;padding:9px 13px;background:var(--o);color:#fff;text-decoration:none;font-weight:700}.btn.gray{background:#edf0f3;color:#27303b}.btn.dark{background:#252b32;color:#fff}.btn.small{padding:6px 9px;border-radius:7px;font-size:13px;line-height:1.2}.quote-table th,.quote-table td{padding:9px 7px}.quote-table th{white-space:nowrap}.quote-table .col-date{width:88px;white-space:nowrap}.quote-table .col-version{width:54px;white-space:nowrap}.quote-table .col-status{width:90px}.quote-table .col-followup{width:104px}.quote-table .col-next{width:118px}.quote-table .col-total{width:92px;white-space:nowrap;text-align:right}.quote-table .col-actions{min-width:260px}.actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.actions form{margin:0}.muted{color:var(--muted)}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid var(--line)}th{font-size:12px;text-transform:uppercase;color:var(--muted)}.pill{display:inline-block;padding:4px 8px;border-radius:20px;background:#edf0f3;font-size:12px}.flash{padding:12px 15px;background:#fff0e5;border:1px solid #ffd2b1;border-radius:9px;margin-bottom:18px}@media(max-width:900px){.main{margin-left:0;padding:22px 18px}}</style></head><body><?php erpSidebar('quotes');?><main class="main"><?php if($msg):?><div class="flash"><?=e($msg)?></div><?php endif;?><div class="row"><div><h1>Presupuestos</h1><p class="muted">Creá presupuestos seleccionando cliente, proyecto y productos del catálogo.</p></div><div class="top-actions"><?php if(($_SESSION['user']['role']??'')==='admin'):?><a class="btn gray" href="?a=quote_rubros">Rubros</a><a class="btn gray" href="?a=quote_pdf_assets">Archivos PDF</a><?php endif;?><a class="btn" href="?a=new_quote">+ Nuevo presupuesto</a></div></div><div class="card" style="border-left:5px solid var(--o)"><b>Seguimiento comercial</b><p class="muted" style="margin-bottom:0">Usá el botón <b>Seguimiento</b> de cada presupuesto para registrar el envío, la respuesta del cliente, agregar notas o programar el próximo contacto.</p></div><div class="card"><div style="overflow:auto"><table class="quote-table"><thead><tr><th class="col-date">Fecha</th><th>Cliente</th><th>Proyecto</th><th>Propuesta</th><th>Rubro</th><th class="col-version">Versión</th><th class="col-status">Estado</th><th class="col-followup">Seguimiento</th><th class="col-next">Próximo contacto</th><th class="col-total">Total</th><th class="col-actions">Acciones</th></tr></thead><tbody><?php if(!$quotes):?><tr><td colspan="11" class="muted">Todavía no hay presupuestos.</td></tr><?php endif;?><?php foreach($quotes as $q):$legacy=(int)$q['item_count']===0;?><tr><td class="col-date"><?=e(date('d/m/Y',strtotime($q['quote_date'])))?></td><td><?=e($q['business_name'])?></td><td><?=e($q['project_number'].' · '.$q['project_name'])?></td><td><?=trim((string)($q['proposal_name']??''))!==''?'<b>'.e($q['proposal_name']).'</b>':'<span class="muted">Sin nombre</span>'?></td><td><?=e($q['quote_category']?:'General')?></td><td class="col-version">v<?=e($q['version_no'])?></td><td class="col-status"><span class="pill"><?=e($statusLabels[$q['status']]??$q['status'])?></span></td><td class="col-followup"><a class="btn small" href="?a=quote_followup&id=<?=$q['id']?>">Seguimiento</a></td><td class="col-next"><?php if($q['followup_closed_at']):?><span class="pill">Cerrado</span><?php elseif($q['next_followup_date']):$due=$q['next_followup_date']<=date('Y-m-d');?><span class="pill" style="<?=$due?'background:#ffe5e5;color:#a92727':''?>"><?=e(date('d/m/Y',strtotime($q['next_followup_date'])))?><?=$due?' · pendiente':''?></span><?php else:?><span class="muted">Sin programar</span><?php endif;?></td><td class="col-total"><?=usd($q['total'])?></td><td class="col-actions"><?php if(!$legacy):?><div class="actions"><a class="btn gray small" href="?a=quote_view&id=<?=$q['id']?>">Ver</a><?php if($q['status']==='borrador'):?><a class="btn dark small" href="?a=edit_quote&id=<?=$q['id']?>">Editar</a><?php else:?><a class="btn dark small" href="?a=quote_state_edit&id=<?=$q['id']?>">Ver / estado</a><form method="post" action="?a=duplicate_quote" onsubmit="return confirm('¿Crear la siguiente versión editable de este presupuesto?')"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="quote_id" value="<?=$q['id']?>"><button class="btn gray small" type="submit">Duplicar</button></form><?php endif;?><?php if($q['status']==='enviado'):?><form method="post" action="?a=quote_status"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="quote_id" value="<?=$q['id']?>"><input type="hidden" name="status" value="aprobado_inicial"><button class="btn small" type="submit">Aceptar inicial</button></form><?php elseif($q['status']==='aprobado_inicial'):?><form method="post" action="?a=quote_status"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="quote_id" value="<?=$q['id']?>"><input type="hidden" name="status" value="aprobado_definitivo"><button class="btn small" type="submit">Aceptar definitivo</button></form><?php endif;?></div><?php else:?><a class="btn gray small" href="?a=project&id=<?=$q['project_id']?>">Abrir proyecto</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>
